class Solution {
  public int divisibleGame(int[] nums) {
    final long MOD = 1_000_000_007L;
    int n = nums.length, MAX = 1_000_001;
    int[] spf = new int[MAX];
    for (int i = 2; i < MAX; i++) {
      if (spf[i] != 0) continue;
      for (int j = i; j < MAX; j += i) if (spf[j] == 0) spf[j] = i;
    }
    java.util.TreeSet<Integer> primes = new java.util.TreeSet<>();
    primes.add(2);
    for (int v : nums)
      for (int x = v; x > 1; ) {
        int p = spf[x];
        primes.add(p);
        while (x % p == 0) x /= p;
      }
    long bestDiff = Long.MIN_VALUE;
    int bestK = 2;
    for (int k : primes) {
      long cur = Long.MIN_VALUE / 4, best = Long.MIN_VALUE;
      for (int v : nums) {
        long val = v % k == 0 ? v : -v;
        cur = Math.max(cur, 0) + val;
        best = Math.max(best, cur);
      }
      if (best > bestDiff) {
        bestDiff = best;
        bestK = k;
      }
    }
    long diff = ((bestDiff % MOD) + MOD) % MOD;
    return (int) (diff * bestK % MOD);
  }
}
